 "content": "from math import gcd
from functools import reduce


def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] not in (0, 8)]
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8]
    if not markers or not cells:
        return out

    mr0 = min(r for r, _ in markers)
    mr1 = max(r for r, _ in markers)
    mc0 = min(c for _, c in markers)
    mc1 = max(c for _, c in markers)
    stencil = [row[mc0:mc1 + 1] for row in grid[mr0:mr1 + 1]]
    # The color stencil is turned clockwise before being mapped to the 8-shaped mosaic.
    stencil = [list(row) for row in zip(*stencil[::-1])]

    row_runs = []
    for r in range(h):
        count = 0
        for c in range(w):
            if grid[r][c] == 8:
                count += 1
            elif count:
                row_runs.append(count)
                count = 0
        if count:
            row_runs.append(count)
    col_runs = []
    for c in range(w):
        count = 0
        for r in range(h):
            if grid[r][c] == 8:
                count += 1
            elif count:
                col_runs.append(count)
                count = 0
        if count:
            col_runs.append(count)
    unit = reduce(gcd, row_runs + col_runs)
    if unit <= 0:
        return out

    r0 = min(r for r, _ in cells)
    c0 = min(c for _, c in cells)
    for r, c in cells:
        sr = (r - r0) // unit
        sc = (c - c0) // unit
        if sr < len(stencil) and sc < len(stencil[0]):
            color = stencil[sr][sc]
            if color:
                out[r][c] = color
    return out


if __name__ == '__main__':
    pass
